/*! xlsx.js (C) 2013-present SheetJS -- http://sheetjs.com */
var XLSX;
XLSX = function() {
    "use strict";
    
    function encode_col(e) {
        if (e < 0) return "A";  // 修复：处理负数列
        var t = "";
        for (++e; e; e = Math.floor((e - 1) / 26)) t = String.fromCharCode(((e - 1) % 26) + 65) + t;
        return t || "A";
    }
    
    function encode_row(e) {
        if (e < 0) return "1";  // 修复：处理负数行
        return "" + (e + 1);
    }
    
    function encode_cell(e) {
        return encode_col(e.c) + encode_row(e.r);
    }
    
    function encode_range(e, t) {
        if (t === undefined) {
            if (typeof e === 'object' && e.s !== undefined) {
                return encode_cell(e.s) + (e.e.c == e.s.c && e.e.r == e.s.r ? "" : ":" + encode_cell(e.e));
            }
            return encode_cell(e);
        }
        return encode_cell(e) + ":" + encode_cell(t);
    }
    
    function decode_col(e) {
        var t = 0, r = 0;
        for (var a = 0; a < e.length; ++a) {
            var n = e.charCodeAt(a);
            if (n >= 65 && n <= 90) {
                t = 26 * t + (n - 64);
            }
        }
        return t - 1;
    }
    
    function decode_row(e) {
        var t = 0;
        for (var r = 0; r < e.length; ++r) {
            var a = e.charCodeAt(r);
            if (a >= 48 && a <= 57) t = 10 * t + (a - 48);
        }
        return t - 1;
    }
    
    function decode_cell(e) {
        var t = 0;
        for (; t < e.length; ++t) if (e.charCodeAt(t) >= 48 && e.charCodeAt(t) <= 57) break;
        return { c: decode_col(e.slice(0, t)), r: decode_row(e.slice(t)) };
    }
    
    function decode_range(e) {
        var t = e.split(":").map(decode_cell);
        return { s: t[0], e: t[1] || t[0] };
    }
    
    function json_to_sheet(e, t) {
        t = t || {};
        var r = t.header || [], a = t.skipHeader || !1, n = {}, s = 0;
        
        // 修复：处理空数据
        if (!e || e.length === 0) {
            return { 
                SheetNames: ["Sheet1"], 
                Sheets: { 
                    Sheet1: { "!ref": "A1:A1" } 
                } 
            };
        }
        
        if (r.length === 0) {
            for (var i in e[0]) if (e[0].hasOwnProperty(i)) r.push(i);
        }
        
        // 修复：如果没有列，添加一个默认列
        if (r.length === 0) {
            r = ["数据"];
        }
        
        if (!a) {
            for (var l = 0; l < r.length; ++l) {
                n[encode_cell({ r: 0, c: l })] = { v: r[l], t: "s" };
            }
            s = 1;
        }
        
        for (var o = 0; o < e.length; ++o) {
            for (var c = 0; c < r.length; ++c) {
                var f = e[o][r[c]];
                if (f !== undefined && f !== null) {
                    var u = typeof f === "number" ? "n" : "s";
                    n[encode_cell({ r: s + o, c: c })] = { v: f, t: u };
                }
            }
        }
        
        var h = { SheetNames: ["Sheet1"], Sheets: { Sheet1: n } };
        var endRow = s + e.length - 1;
        var endCol = r.length - 1;
        // 修复：确保范围有效
        if (endRow < 0) endRow = 0;
        if (endCol < 0) endCol = 0;
        h.Sheets.Sheet1["!ref"] = encode_range({ s: { c: 0, r: 0 }, e: { c: endCol, r: endRow } });
        return h;
    }
    
    function sheet_to_csv(e) {
        var t = [], r = decode_range(e["!ref"] || "A1:A1");
        for (var a = r.s.r; a <= r.e.r; ++a) {
            var n = [];
            for (var s = r.s.c; s <= r.e.c; ++s) {
                var i = e[encode_cell({ c: s, r: a })];
                n.push(i ? ("" + i.v).replace(/,/g, "") : "");
            }
            t.push(n.join(","));
        }
        return t.join("\n");
    }
    
    // 读取Excel文件（简化版，支持CSV和基本XML格式）
    function read(e, t) {
        t = t || {};
        var data;
        
        if (t.type === 'array') {
            // 将Uint8Array转换为字符串
            try {
                data = String.fromCharCode.apply(null, e);
            } catch (err) {
                // 如果数组太大，分段处理
                var chunks = [];
                var chunkSize = 65536;
                for (var i = 0; i < e.length; i += chunkSize) {
                    chunks.push(String.fromCharCode.apply(null, e.subarray(i, i + chunkSize)));
                }
                data = chunks.join('');
            }
        } else if (t.type === 'binary') {
            data = e;
        } else {
            data = e;
        }
        
        // 检测文件类型
        // 检查是否是ZIP格式（现代.xlsx文件）
        if (data.charCodeAt(0) === 0x50 && data.charCodeAt(1) === 0x4B) {
            // 这是ZIP格式，尝试解析为简化的工作簿
            return parseZipWorkbook(data);
        } else if (data.indexOf('<?xml') !== -1 || data.indexOf('<Workbook') !== -1) {
            // XML格式（Excel 2003 XML格式）
            return parseXMLWorkbook(data);
        } else {
            // 尝试作为CSV解析
            return parseCSVWorkbook(data);
        }
    }
    
    // 解析ZIP格式的工作簿（简化版）
    function parseZipWorkbook(zipData) {
        // 尝试从ZIP中提取sharedStrings.xml和sheet1.xml
        // 这是一个简化的实现，假设数据是CSV格式
        
        // 尝试找到工作表数据
        var sheetMatch = zipData.match(/sheet1\.xml[^]*?<worksheet[^]*?<sheetData[^]*?<\/sheetData>/i);
        if (sheetMatch) {
            return parseXLSXSheet(sheetMatch[0]);
        }
        
        // 如果无法解析，尝试作为CSV处理
        // 移除ZIP文件中的二进制数据，尝试提取文本
        var textData = zipData.replace(/[^\x20-\x7E\u4e00-\u9fa5\n\r\t]/g, '');
        if (textData.indexOf(',') !== -1 || textData.indexOf('\t') !== -1) {
            return parseCSVWorkbook(textData);
        }
        
        // 返回空工作簿
        return {
            SheetNames: ["Sheet1"],
            Sheets: {
                "Sheet1": {
                    "!ref": "A1:A1"
                }
            }
        };
    }
    
    // 解析XLSX工作表
    function parseXLSXSheet(xmlStr) {
        var sheet = {};
        var rowRegex = /<row[^>]*>([\s\S]*?)<\/row>/gi;
        var cellRegex = /<c[^>]*>([\s\S]*?)<\/c>/gi;
        var valueRegex = /<v>([^<]*)<\/v>/i;
        var maxRow = 0, maxCol = 0;
        
        var rowMatch;
        while ((rowMatch = rowRegex.exec(xmlStr)) !== null) {
            var rowXml = rowMatch[1];
            var rowAttr = rowMatch[0].match(/r="(\d+)"/);
            var rowNum = rowAttr ? parseInt(rowAttr[1]) - 1 : 0;
            
            var cellMatch;
            while ((cellMatch = cellRegex.exec(rowXml)) !== null) {
                var cellXml = cellMatch[0];
                var cellRef = cellXml.match(/r="([A-Z]+\d+)"/);
                
                if (cellRef) {
                    var cellAddr = cellRef[1];
                    var cell = decode_cell(cellAddr);
                    
                    var valueMatch = cellXml.match(valueRegex);
                    if (valueMatch) {
                        var value = valueMatch[1];
                        var numVal = parseFloat(value);
                        
                        if (!isNaN(numVal) && isFinite(numVal)) {
                            sheet[cellAddr] = { v: numVal, t: "n" };
                        } else {
                            sheet[cellAddr] = { v: value, t: "s" };
                        }
                        
                        maxRow = Math.max(maxRow, cell.r);
                        maxCol = Math.max(maxCol, cell.c);
                    }
                }
            }
        }
        
        sheet["!ref"] = encode_range({ s: { r: 0, c: 0 }, e: { r: maxRow, c: maxCol } });
        
        return {
            SheetNames: ["Sheet1"],
            Sheets: {
                "Sheet1": sheet
            }
        };
    }
    
    // 解析XML格式的工作簿
    function parseXMLWorkbook(xmlStr) {
        var sheetName = "Sheet1";
        var sheet = {};
        var row = 0, col = 0;
        var inCell = false, inData = false;
        var cellValue = "";
        var cellType = "s";
        
        // 简单的XML解析
        var rows = xmlStr.match(/<Row[^>]*>[\s\S]*?<\/Row>/g) || [];
        
        rows.forEach(function(rowXml, r) {
            var cells = rowXml.match(/<Cell[^>]*>[\s\S]*?<\/Cell>/g) || [];
            cells.forEach(function(cellXml, c) {
                // 获取列索引
                var cellRef = cellXml.match(/ss:Index="(\d+)"/);
                if (cellRef) {
                    c = parseInt(cellRef[1]) - 1;
                }
                
                // 获取数据
                var dataMatch = cellXml.match(/<Data[^>]*>([\s\S]*?)<\/Data>/);
                if (dataMatch) {
                    var value = dataMatch[1].trim();
                    var typeMatch = cellXml.match(/ss:Type="([^"]+)"/);
                    var type = "s";
                    if (typeMatch && typeMatch[1] === "Number") {
                        type = "n";
                        value = parseFloat(value);
                    }
                    
                    sheet[encode_cell({ r: r, c: c })] = { v: value, t: type };
                }
            });
        });
        
        // 设置范围
        var maxRow = 0, maxCol = 0;
        for (var key in sheet) {
            if (key.startsWith('!')) continue;
            var cell = decode_cell(key);
            maxRow = Math.max(maxRow, cell.r);
            maxCol = Math.max(maxCol, cell.c);
        }
        sheet["!ref"] = encode_range({ s: { r: 0, c: 0 }, e: { r: maxRow, c: maxCol } });
        
        var result = {
            SheetNames: [sheetName],
            Sheets: {}
        };
        result.Sheets[sheetName] = sheet;
        return result;
    }
    
    // 解析CSV格式的工作簿
    function parseCSVWorkbook(csvStr) {
        var lines = csvStr.trim().split('\n');
        var sheet = {};
        var maxCol = 0;
        
        lines.forEach(function(line, r) {
            var values = parseCSVLine(line);
            maxCol = Math.max(maxCol, values.length - 1);
            
            values.forEach(function(value, c) {
                value = value.trim();
                if (value) {
                    var numVal = parseFloat(value);
                    if (!isNaN(numVal) && isFinite(numVal)) {
                        sheet[encode_cell({ r: r, c: c })] = { v: numVal, t: "n" };
                    } else {
                        sheet[encode_cell({ r: r, c: c })] = { v: value, t: "s" };
                    }
                }
            });
        });
        
        // 设置范围
        sheet["!ref"] = encode_range({ 
            s: { r: 0, c: 0 }, 
            e: { r: lines.length - 1, c: maxCol } 
        });
        
        return {
            SheetNames: ["Sheet1"],
            Sheets: { "Sheet1": sheet }
        };
    }
    
    // sheet_to_json函数
    function sheet_to_json(sheet, opts) {
        opts = opts || {};
        var range = decode_range(sheet["!ref"] || "A1:A1");
        var result = [];
        var header = opts.header || 1;
        
        for (var r = range.s.r; r <= range.e.r; ++r) {
            var row = {};
            var rowArray = [];
            var hasData = false;
            
            for (var c = range.s.c; c <= range.e.c; ++c) {
                var cell = sheet[encode_cell({ r: r, c: c })];
                var value = cell ? cell.v : "";
                
                if (value !== "" && value !== undefined && value !== null) {
                    hasData = true;
                }
                
                if (header === 1) {
                    // 第一行作为表头
                    if (r === range.s.r) {
                        rowArray.push(value);
                    } else {
                        var headerName = sheet[encode_cell({ r: range.s.r, c: c })];
                        headerName = headerName ? headerName.v : "Column" + c;
                        row[headerName] = value;
                    }
                } else {
                    row["Column" + c] = value;
                }
            }
            
            if (hasData) {
                if (header === 1 && r > range.s.r) {
                    result.push(row);
                } else if (header !== 1) {
                    result.push(row);
                }
            }
        }
        
        return result;
    }
    
    // 解析CSV行
    function parseCSVLine(line) {
        var result = [];
        var current = '';
        var inQuotes = false;
        
        for (var i = 0; i < line.length; i++) {
            var char = line[i];
            
            if (char === '"') {
                inQuotes = !inQuotes;
            } else if (char === ',' && !inQuotes) {
                result.push(current.trim());
                current = '';
            } else {
                current += char;
            }
        }
        
        result.push(current.trim());
        return result;
    }
    
    function write(e, t) {
        t = t || {};
        var r = t.bookType || "xlsx";
        
        if (r === "csv") {
            return sheet_to_csv(e.Sheets[e.SheetNames[0]]);
        }
        
        var a = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\r\n';
        a += '<?mso-application progid="Excel.Sheet"?>\r\n';
        a += '<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">\r\n';
        a += '<Worksheet ss:Name="' + (e.SheetNames[0] || "Sheet1") + '">\r\n';
        a += '<Table>\r\n';
        
        var n = e.Sheets[e.SheetNames[0]] || {};
        var s = decode_range(n["!ref"] || "A1:A1");
        
        for (var i = s.s.r; i <= s.e.r; ++i) {
            a += '<Row>\r\n';
            for (var l = s.s.c; l <= s.e.c; ++l) {
                var o = n[encode_cell({ c: l, r: i })];
                if (o) {
                    var c = o.t === "n" ? "Number" : "String";
                    a += '<Cell><Data ss:Type="' + c + '">' + o.v + '</Data></Cell>\r\n';
                } else {
                    a += '<Cell><Data ss:Type="String"></Data></Cell>\r\n';
                }
            }
            a += '</Row>\r\n';
        }
        
        a += '</Table>\r\n';
        a += '</Worksheet>\r\n';
        a += '</Workbook>';
        
        return a;
    }
    
    function writeFile(e, t, r) {
        r = r || {};
        var a = write(e, r);
        var n = new Blob([a], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
        var s = document.createElement("a");
        s.href = URL.createObjectURL(n);
        s.download = t;
        document.body.appendChild(s);
        s.click();
        document.body.removeChild(s);
        URL.revokeObjectURL(s.href);
    }
    
    function book_new() {
        return { SheetNames: [], Sheets: {} };
    }
    
    function book_append_sheet(e, t, r) {
        e.SheetNames.push(r || "Sheet" + (e.SheetNames.length + 1));
        e.Sheets[e.SheetNames[e.SheetNames.length - 1]] = t;
    }
    
    return {
        utils: {
            json_to_sheet: json_to_sheet,
            sheet_to_json: sheet_to_json,
            encode_col: encode_col,
            encode_row: encode_row,
            encode_cell: encode_cell,
            encode_range: encode_range,
            decode_col: decode_col,
            decode_row: decode_row,
            decode_cell: decode_cell,
            decode_range: decode_range,
            sheet_to_csv: sheet_to_csv,
            book_new: book_new,
            book_append_sheet: book_append_sheet
        },
        read: read,
        write: write,
        writeFile: writeFile
    };
}();
